}

function 数组() {
  const nums = [1, 2, 3, 4];
  const 双倍 = nums.map((v) => v * 2);
  const 偶数 = nums.filter((v) => v % 2 === 0);
  console.log(双倍, 偶数);
}

function 写一列() {
  const s = Sheets.Item(1);
  const arr = ["甲", "乙", "丙"];
  arr.forEach((v, i) => {
    s.Range("A" + (i + 1)).Value2 = v;
  });
}

syntax:
const o = { 名称: "张三", 分数: 90 };
JSON.stringify(o)
JSON.parse(text)

examples.code:
function 转文本() {
  const o = { 名称: "张三", 分数: 90 };
  alert(JSON.stringify(o));
}

function 转对象() {
  const text = `{"名称":"李四","分数":88}`;
  const o = JSON.parse(text);
  alert(o.名称 + ":" + o.分数);
}

syntax:
try {
  // 可能出错
} catch (e) {
  // 处理
} finally {
  // 收尾
}

examples.code:
function 捕获() {
  try {
    const v = null;
    alert(v.length);
  } catch (e) {
    alert("出错：" + e.message);
  }
}

function 校验(n) {
  if (n < 0) {
    throw new Error("不能为负数");
  }
  return n;
}

function 测试() {
  try { 校验(-1); } catch (e) { alert(e.message); }
}

function 单格() {
  const s = Sheets.Item(1);
  s.Range("A1").Value2 = 123;
  const v = s.Range("A1").Value2;
  console.log(v, typeof v);
}

function 批量() {
  const s = Sheets.Item(1);
  const data = [["姓名", "分数"], ["张三", 90], ["李四", 88]];
  s.Range("A1").Resize(3, 2).Value2 = data;
  const back = s.Range("A1:B3").Value2;
  console.log(back);
}

function 日志() {
  const a = 1, b = "二";
  console.log("a=", a, "b=", b);
}

function 看对象() {
  const o = { 名称: "张三", 分数: 90 };
  console.log(JSON.stringify(o));
}
